import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"Timestamp 时间戳","description":"","frontmatter":{},"headers":[],"relativePath":"components/timestamp.md","filePath":"components/timestamp.md","lastUpdated":1791177194000}`),l={name:`components/timestamp.md`};function u(a,c,l,u,d,f){let p=e(`XhDemo`);return t(),i(`div`,null,[c[0]||=s(`<h1 id="timestamp-时间戳" tabindex="-1">Timestamp 时间戳 <a class="header-anchor" href="#timestamp-时间戳" aria-label="Permalink to “Timestamp 时间戳”">​</a></h1><p>把一个时刻渲染成文本，绝对或相对。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/timestamp" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/timestamp.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/timestamp" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/timestamp" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/timestamp.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>渲染为 &lt;time datetime&gt;：文本供人阅读，datetime 供机器读取，两者取自同一个墙钟</p>`,5),r(p,{src:`timestamp/01-basic`}),c[1]||=s(`<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to “组件结构”">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;timestamp&quot;</code>：<strong><code>root</code></strong></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><h3 id="呈现方式" tabindex="-1">呈现方式 <a class="header-anchor" href="#呈现方式" aria-label="Permalink to “呈现方式”">​</a></h3><p>date 只到日、datetime 到秒、relative 表述为几分钟前等相对说法；datetime 属性的精度随之变化</p>`,6),r(p,{src:`timestamp/02-type`}),c[2]||=o(`h3`,{id:`自定义格式串`,tabindex:`-1`},[n(`自定义格式串 `),o(`a`,{class:`header-anchor`,href:`#自定义格式串`,"aria-label":`Permalink to “自定义格式串”`},`​`)],-1),c[3]||=o(`p`,null,`记号是 YYYY / YY / MM / M / DD / D / HH / H / mm / m / ss / s，只改变看到的文本，datetime 不随之变化`,-1),r(p,{src:`timestamp/03-format`}),c[4]||=o(`h3`,{id:`相对时间`,tabindex:`-1`},[n(`相对时间 `),o(`a`,{class:`header-anchor`,href:`#相对时间`,"aria-label":`Permalink to “相对时间”`},`​`)],-1),c[5]||=o(`p`,null,`一分钟以内是「现在」，其余按分、时、天取整，过去说「几分钟前」、将来说「几分钟后」，离现在三十天及以上退回绝对日期；用词由 Intl 按 locale 给出，未提供时跟随浏览器语言`,-1),r(p,{src:`timestamp/04-relative`}),c[6]||=o(`h3`,{id:`自动刷新`,tabindex:`-1`},[n(`自动刷新 `),o(`a`,{class:`header-anchor`,href:`#自动刷新`,"aria-label":`Permalink to “自动刷新”`},`​`)],-1),c[7]||=o(`p`,null,`相对型不给 now 时自己刷新：文字只在跨过分钟、小时、天的边界时才变，就只在那一刻刷新；页面隐藏或离开视口时暂停，回来时立即补一次`,-1),r(p,{src:`timestamp/05-live`}),c[8]||=o(`h3`,{id:`时区`,tabindex:`-1`},[n(`时区 `),o(`a`,{class:`header-anchor`,href:`#时区`,"aria-label":`Permalink to “时区”`},`​`)],-1),c[9]||=o(`p`,null,`time-zone 给了 IANA 时区名就按那个时区的墙钟显示，datetime 带上该时区的偏移量；不带偏移量的 value 串也按这个时区解读`,-1),r(p,{src:`timestamp/06-time-zone`}),c[10]||=s(`<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to “设计指引”">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h3><ul><li>展示创建时间、更新时间、事件发生时刻。</li><li>需要“n 分钟前”“n 分钟后”等相对表述，并随时间推移自己刷新。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to “何时不用”">​</a></h3><ul><li>需要倒数剩余时长时，使用<a href="./timer">计时器</a>。</li><li>需要用户选择时间时，使用<a href="./time-picker">时间选择器</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li><code>type</code> 切换绝对与相对；相对说法一分钟以内是「现在」，其余按分、时、天取整，过去与将来都认，离现在三十天及以上退回绝对日期。</li><li>用词与缺省日期写法由 <code>Intl.RelativeTimeFormat</code> / <code>Intl.DateTimeFormat</code> 按 <code>locale</code> 给出，任何语言都可用；未提供时跟随宿主浏览器语言，读取失败时使用 <code>en-US</code>。<code>translations.justNow</code> 可换掉「现在」那一档的说法。</li><li><code>format</code> 自定义格式串，只改变显示文本，<code>datetime</code> 属性不变。</li><li><code>timeZone</code> 给了 IANA 时区名就按那个时区的墙钟显示，<code>datetime</code> 带上偏移量；不带偏移量的 <code>value</code> 串也按这个时区解读。认不出的时区落 <code>invalid</code>。</li><li>相对型不给 <code>now</code> 时自动刷新：文字只在跨过分钟、小时、天的边界时才变，就只在那一刻刷新；页面隐藏或元素离开视口时暂停，回来时立即补一次。<code>refreshInterval</code> 改成固定间隔，给 0 不刷新；它是停留时长，不受减弱动效影响。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to “组合”">​</a></h3><ul><li>放入<a href="./list">列表</a>的条目、<a href="./table">表格</a>的单元格、<a href="./timeline">时间线</a>的时间位。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li>相对时间旁给出绝对时间（提示或 <code>title</code>），“3 天前”在追查问题时不够用。</li><li>时区要明确：跨时区团队中“昨天”是含糊的说法，给 <code>timeZone</code> 让所有人看到同一个墙钟。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to “反模式”">​</a></h3><ul><li>只给相对时间且无法看到确切时刻。</li><li>对很久以前的事仍用相对表述（“427 天前”）。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to “产物”">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-timestamp&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTimestamp</code></td></tr><tr><td>状态机</td><td><code>timestampMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/timestamp.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to “Props”">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>format</code></td><td><code>string</code></td><td></td><td>自定义格式串，记号为 YYYY / YY / MM / M / DD / D / HH / H / mm / m / ss / s。 提供后覆盖该语言的缺省写法；relative 型下只在回退为绝对日期时使用。</td></tr><tr><td><code>locale</code></td><td><code>string</code></td><td></td><td>BCP 47 语言标记，决定相对说法的用词与缺省的日期写法，任何语言都由 Intl 给出。 未提供时按宿主语言，宿主也没有时按 en-US。它只切换面向用户的文本，datetime 与语言无关。</td></tr><tr><td><code>now</code></td><td><code>TimestampValue</code></td><td></td><td>计算相对说法时的参照时刻，默认取当前时刻并自动刷新。提供后整个组件的产出完全由入参决定，不再刷新。</td></tr><tr><td><code>refreshInterval</code></td><td><code>number</code></td><td></td><td>相对型的刷新间隔（毫秒）。缺省按距今远近自适应：文字只在跨过分钟、小时、天的边界时才变， 就只在那一刻刷新；给正数按固定间隔刷新，给 0 不刷新。页面隐藏或元素离开视口时暂停，回来时立即刷新一次。 这是停留时长，不是动效，不受减弱动效影响。</td></tr><tr><td><code>timeZone</code></td><td><code>string</code></td><td></td><td>IANA 时区名（如 <code>Asia/Shanghai</code>）。给了就按这个时区的墙钟显示，datetime 带上该时区的偏移量； 不带偏移量的 <code>value</code> 串也按这个时区解读。未提供时按运行时本地、datetime 不带偏移量。认不出的时区落 invalid。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TimestampTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>type</code></td><td><code>TimestampType</code></td><td></td><td>呈现方式：date 只到日、datetime 到秒、relative 表述为「几分钟前」「几分钟后」，默认 datetime。</td></tr><tr><td><code>value</code></td><td><code>TimestampValue</code></td><td></td><td>要显示的时刻。只写年月日的串按零点解读；不带偏移量的串按 <code>timeZone</code> 的墙钟解读，没给时区时按本地。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to “状态”">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;empty&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>live</code></p><p><strong>事件</strong>：<code>REFRESH.SYNC</code> · <code>TICK</code></p><p><strong>判据</strong>：<code>shouldRefresh</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to “connect API”">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>date</code></td><td><code>Date | undefined</code></td><td>解析出的时刻；未提供或无法识别时为 undefined。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>面向用户的文本；没有可读时刻时为空串。</td></tr><tr><td><code>stamp</code></td><td><code>string | undefined</code></td><td>写入 datetime 的时间戳；没有可读时刻时为 undefined，此时根上不写该属性。</td></tr><tr><td><code>state</code></td><td><code>TimestampState</code></td><td>当前状态。</td></tr><tr><td><code>relative</code></td><td><code>boolean</code></td><td>本次是否实际按相对说法朗读。离现在三十天及以上回退为绝对日期时为 false。</td></tr><tr><td><code>refreshing</code></td><td><code>boolean</code></td><td>正在按时刷新相对说法。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to “无障碍”">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to “键盘”">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to “样式参考”">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to “皮肤”">​</a></h3><p><code>@xihan-ui/styles/timestamp.css</code> 按 <code>[data-scope=&quot;timestamp&quot;][data-part=&quot;root&quot;]</code> 部件选择器书写，发布产物以挂载类 <code>.xh-scope-timestamp</code> 代替其中的 data-scope（特异性相同），位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>，部件选择器照常可用。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to “数据属性”">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-format</code></td><td>props.type</td></tr><tr><td><code>root</code></td><td><code>data-relative</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;empty&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to “CSS 变量”">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-timestamp-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>timestamp 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-timestamp-placeholder-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>state=empty</code><br><code>state=invalid</code></td><td><code>--xh-fg-muted</code></td><td>timestamp 的 root 部件 color 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to “动效”">​</a></h3><p>动效角色：状态（见<a href="./../design/motion#角色">动效规范</a>）。</p><p><code>color</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p>`,45)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};